/* 図柄画像の埋め込み (240x120)。ファイル配置やキャッシュに依存しないための本体。自動生成 */
const SYM_IMG = {"7red": "data:image/png;base64,", "7blue": "data:image/png;base64,", "7white": "data:image/png;base64,", "bar": "data:image/png;base64,", "bell": "data:image/png;base64,", "cherry": "data:image/png;base64,", "replay": "data:image/png;base64,", "melon": "data:image/png;base64,"};

/* リール回転を軽くする: base64の長い文字列(1枚あたり約50KB)をBlobのURLに変換する。
   回転中は図柄が毎フレームのように差し替わるため、長い文字列のままだと解析・デコードが重くコマ落ちする */
(function () {
  try {
    Object.keys(SYM_IMG).forEach(k => {
      const m = /^data:([^;]+);base64,(.*)$/.exec(SYM_IMG[k]);
      if (!m) return;
      const bin = atob(m[2]), arr = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
      SYM_IMG[k] = URL.createObjectURL(new Blob([arr], { type: m[1] }));
      const im = new Image(); im.src = SYM_IMG[k]; if (im.decode) im.decode().catch(() => {});   // 先にデコードしておく
    });
  } catch (e) { /* 変換できなければ元のまま */ }
})();
